class ProjectEngineeringPolicy:
    """Deep interface for one exact project engineering-policy revision."""

    def __init__(
        self,
        project_dir: str | Path,
        policy_path: str,
        *,
        observed_ref: str | None = None,
        shared_reader: GitProjectReader | None = None,
    ) -> None:
        try:
            self.reader = project_reader_for_scope(
                project_dir,
                observed_ref=observed_ref,
                shared_reader=shared_reader,
            )
            self.policy_path = repository_relative_path(
                policy_path,
                "engineering_policy_path",
            )
        except GitProjectReaderError as error:
            raise ProjectEngineeringPolicyError([str(error)]) from error
        self.project = self.reader.project
        self.observed_commit = self.reader.observed_commit
        self._policy_cache: dict[str, Any] | None = None

    def load(self) -> dict[str, Any]:
        if self._policy_cache is not None:
            return deepcopy(self._policy_cache)
        try:
            value = self.reader.load_yaml(self.policy_path, "项目工程政策")
        except GitProjectReaderError as error:
            raise ProjectEngineeringPolicyError([str(error)]) from error
        if not isinstance(value, Mapping):
            raise ProjectEngineeringPolicyError(["项目工程政策必须是对象"])
        if value.get("schema_version") != ENGINEERING_POLICY_SCHEMA:
            raise ProjectEngineeringPolicyError(
                ["项目工程政策必须使用当前第一版结构合同，旧混合基线不再裁决政策"]
            )
        issues = _schema_issues(value)
        try:
            self.reader.prefetch(
                [
                    repository_relative_path(
                        source.get("path"),
                        f"project_sources[{index}].path",
                    )
                    for index, source in enumerate(value.get("project_sources", []))
                    if isinstance(source, Mapping)
                ]
            )
        except GitProjectReaderError as error:
            issues.append(str(error))
        base_profile = load_base_governance_profile()
        base_ref = value.get("base_profile_ref") or {}
        if base_ref != {
            "profile_id": base_profile["profile_id"],
            "profile_version": base_profile["profile_version"],
        }:
            issues.append("项目工程政策没有绑定当前随包基础治理档案的精确版本")

        method_by_id = {
            str(method["method_id"]): method
            for method in base_profile["engineering_methods"]
        }
        adoption_ids: set[str] = set()
        for adoption in value.get("method_adoptions", []):
            if not isinstance(adoption, Mapping):
                continue
            method_id = str(adoption.get("method_id") or "")
            if method_id in adoption_ids:
                issues.append(f"项目工程方法采用身份重复：{method_id}")
            adoption_ids.add(method_id)
            method = method_by_id.get(method_id)
            if method is None:
                issues.append(f"项目工程方法采用引用未知方法：{method_id}")
                continue
            known_techniques = {
                str(item["technique_id"]) for item in method["techniques"]
            }
            adopted = set(adoption.get("adopted_technique_ids") or [])
            unknown = sorted(adopted - known_techniques)
            if unknown:
                issues.append(
                    f"{method_id} 采用状态引用未知技术：" + ", ".join(unknown)
                )
            if adoption.get("status") in {"adopted", "conditional"}:
                missing = sorted(
                    set(method["project_adoption_requires"]) - adopted
                )
                if missing:
                    issues.append(
                        f"{method_id} 项目采用缺少必要技术："
                        + ", ".join(missing)
                    )

        source_ids = {
            str(source["source_id"]) for source in base_profile["sources"]
        }
        for index, source in enumerate(value.get("project_sources", [])):
            if not isinstance(source, Mapping):
                continue
            source_id = str(source.get("source_id") or "")
            if source_id in source_ids:
                issues.append(f"项目工程政策来源身份冲突：{source_id}")
            source_ids.add(source_id)
            try:
                source_path = repository_relative_path(
                    source.get("path"),
                    f"project_sources[{index}].path",
                )
                if not self.reader.exists(source_path):
                    issues.append(f"项目工程政策来源不存在：{source_path}")
            except GitProjectReaderError as error:
                issues.append(str(error))

        base_rule_by_id = {
            str(rule["rule_id"]): rule for rule in base_profile["rules"]
        }
        extension_ids: set[str] = set()
        for extension in value.get("rule_extensions", []):
            if not isinstance(extension, Mapping):
                continue
            rule_id = str(extension.get("rule_id") or "")
            if rule_id in base_rule_by_id or rule_id in extension_ids:
                issues.append(f"项目工程政策扩展规则身份冲突：{rule_id}")
            extension_ids.add(rule_id)
            unknown_sources = sorted(
                set(extension.get("source_ids") or []) - source_ids
            )
            if unknown_sources:
                issues.append(
                    f"项目工程政策扩展规则 {rule_id} 引用未知来源："
                    + ", ".join(unknown_sources)
                )
            unknown_dimensions = sorted(
                set(extension.get("impact_dimensions") or [])
                - IMPACT_DIMENSIONS
            )
            if unknown_dimensions:
                issues.append(
                    f"项目工程政策扩展规则 {rule_id} 包含未知影响维度："
                    + ", ".join(unknown_dimensions)
                )
            unknown_kinds = sorted(
                set(extension.get("required_information_kinds") or [])
                - INFORMATION_KINDS
            )
            if unknown_kinds:
                issues.append(
                    f"项目工程政策扩展规则 {rule_id} 包含未知信息种类："
                    + ", ".join(unknown_kinds)
                )

        tailored: set[str] = set()
        for tailoring in value.get("rule_tailoring", []):
            if not isinstance(tailoring, Mapping):
                continue
            rule_id = str(tailoring.get("rule_id") or "")
            if rule_id in tailored:
                issues.append(f"项目工程政策规则重复裁剪：{rule_id}")
            tailored.add(rule_id)
            rule = base_rule_by_id.get(rule_id)
            if rule is None:
                issues.append(f"项目工程政策裁剪引用未知规则：{rule_id}")
                continue
            requested = tailoring.get("minimum_assurance")
            disposition = tailoring.get("disposition")
            if disposition == "strengthened":
                if requested is None:
                    issues.append(f"{rule_id} 强化时必须声明最低保障等级")
                elif ASSURANCE_BANDS.index(str(requested)) < ASSURANCE_BANDS.index(
                    str(rule["minimum_assurance"])
                ):
                    issues.append(f"{rule_id} 的强化不得降低最低保障等级")
            elif requested is not None:
                issues.append(f"{rule_id} 非强化裁剪不得声明最低保障等级")

        verification_policy = value.get("verification_command_policy")
        if isinstance(verification_policy, Mapping):
            forbidden_programs = {
                str(item).strip().casefold()
                for item in verification_policy.get(
                    "forbidden_agent_program_names"
                )
                or []
            }
            missing_forbidden = sorted(
                REQUIRED_FORBIDDEN_AGENT_PROGRAM_NAMES - forbidden_programs
            )
            if missing_forbidden:
                issues.append(
                    "项目验证政策缺少必须禁止的智能编码代理程序："
                    + ", ".join(missing_forbidden)
                )
            allowed_identities: set[str] = set()
            for index, allowed in enumerate(
                verification_policy.get("allowed_programs") or []
            ):
                if not isinstance(allowed, Mapping):
                    continue
                program = str(allowed.get("program") or "")
                normalized = program.replace("\\", "/").casefold()
                name = Path(normalized).name.casefold()
                stem = Path(name).stem.casefold()
                identity = normalized.removeprefix("./")
                if identity in allowed_identities:
                    issues.append(
                        "项目验证政策允许程序身份重复：" + program
                    )
                allowed_identities.add(identity)
                if {name, stem} & forbidden_programs:
                    issues.append(
                        f"项目验证政策 allowed_programs[{index}] 同时允许并禁止代理程序"
                    )

        revision = value.get("revision") or {}
        if revision.get("status") == "confirmed" and value.get(
            "unresolved_decisions"
        ):
            issues.append("已确认项目工程政策不得保留未决事项")
        if issues:
            raise ProjectEngineeringPolicyError(issues)
        normalized = deepcopy(dict(value))
        normalized["_manifest_path"] = self.policy_path
        normalized["_observed_commit"] = self.observed_commit
        normalized["_semantic_content_machine_proven"] = False
        self._policy_cache = normalized
        return deepcopy(normalized)

    def governance_profile(self) -> dict[str, Any]:
        """Return the exact deterministic profile consumed by assessment governance."""

        policy = self.load()
        profile = load_base_governance_profile()
        source_ids = {str(item["source_id"]) for item in profile["sources"]}
        for source in policy["project_sources"]:
            source_id = str(source["source_id"])
            if source_id in source_ids:
                continue
            profile["sources"].append(
                {
                    "source_id": source_id,
                    "source_kind": "project_artifact",
                    "designation": source_id,
                    "title": source["title"],
                    "edition": policy["revision"]["revision_id"],
                    "status": source["status"],
                    "location": source["path"],
                    "verified_on": policy["revision"]["confirmed_on"],
                    "usage": source["usage"],
                }
            )
            source_ids.add(source_id)
        rule_by_id = {str(rule["rule_id"]): rule for rule in profile["rules"]}
        for tailoring in policy["rule_tailoring"]:
            rule = rule_by_id[str(tailoring["rule_id"])]
            rule["project_tailoring"] = {
                "disposition": tailoring["disposition"],
                "reason": tailoring["reason"],
                "owner_confirmed": True,
            }
            if tailoring["disposition"] == "project_not_applicable":
                rule["project_not_applicable"] = True
            elif tailoring["disposition"] == "strengthened":
                rule["minimum_assurance"] = tailoring["minimum_assurance"]
        for extension in policy["rule_extensions"]:
            profile["rules"].append(deepcopy(extension))
        profile["project_tailoring"] = deepcopy(policy["rule_tailoring"])
        profile["project_method_adoptions"] = deepcopy(
            policy["method_adoptions"]
        )
        profile["project_policy_statements"] = deepcopy(
            policy["policy_statements"]
        )
        profile["verification_command_policy"] = deepcopy(
            policy["verification_command_policy"]
        )
        profile["project_engineering_policy_ref"] = {
            "policy_id": policy["policy_id"],
            "revision_id": policy["revision"]["revision_id"],
            "path": self.policy_path,
            "observed_commit": self.observed_commit,
        }
        profile["profile_id"] = (
            f"{profile['profile_id']}+{policy['policy_id']}"
        )
        return profile

    def obligations(
        self,
        impact_dimensions: Sequence[str],
        assurance_band: str,
    ) -> dict[str, Any]:
        """Project explicit policy rules onto already supplied impact facts."""

        unknown_dimensions = sorted(set(impact_dimensions) - IMPACT_DIMENSIONS)
        if unknown_dimensions:
            raise ProjectEngineeringPolicyError(
                ["未知影响维度：" + ", ".join(unknown_dimensions)]
            )
        if assurance_band not in ASSURANCE_BANDS:
            raise ProjectEngineeringPolicyError(
                ["未知保障等级：" + str(assurance_band)]
            )
        profile = self.governance_profile()
        selected: list[dict[str, Any]] = []
        required_band = "A0"
        for rule in profile["rules"]:
            if rule.get("project_not_applicable"):
                continue
            applies = bool(rule["always_for_formal_implementation"]) or bool(
                set(rule["impact_dimensions"]) & set(impact_dimensions)
            )
            if not applies:
                continue
            selected.append(deepcopy(rule))
            if ASSURANCE_BANDS.index(str(rule["minimum_assurance"])) > (
                ASSURANCE_BANDS.index(required_band)
            ):
                required_band = str(rule["minimum_assurance"])
        return {
            "schema_version": "strixnova.project-engineering-obligations.v1",
            "policy_ref": profile["project_engineering_policy_ref"],
            "supplied_impact_dimensions": sorted(set(impact_dimensions)),
            "supplied_assurance_band": assurance_band,
            "minimum_required_assurance_band": required_band,
            "rules": selected,
            "semantic_content_machine_proven": False,
        }

def __init__(
    self,
    project_dir: str | Path,
    alignment_path: str,
    *,
    domain_model_path: str,
    architecture_description_path: str,
    observed_ref: str | None = None,
    shared_reader: GitProjectReader | None = None,
    domain_reader: ProjectDomainModel | None = None,
    architecture_reader: ProjectArchitectureDescription | None = None,
    repository_readers: Mapping[str | None, GitProjectReader] | None = None,
) -> None:
    try:
        self.reader = project_reader_for_scope(
            project_dir,
            observed_ref=observed_ref,
            shared_reader=shared_reader,
        )
        self.alignment_path = repository_relative_path(
            alignment_path,
            "implementation_alignment_path",
        )
        self.domain_model_path = repository_relative_path(
            domain_model_path,
            "domain_model_path",
        )
        self.architecture_description_path = repository_relative_path(
            architecture_description_path,
            "architecture_description_path",
        )
    except GitProjectReaderError as error:
        raise ProjectImplementationAlignmentError([str(error)]) from error
    self.project = self.reader.project
    self.observed_commit = self.reader.observed_commit
    self.repository_readers = dict(repository_readers or {self.reader.repository_id: self.reader})
    self.domain_model = domain_reader or ProjectDomainModel(
        self.project,
        self.domain_model_path,
        shared_reader=self.reader,
    )
    self.architecture = architecture_reader or ProjectArchitectureDescription(
        self.project,
        self.architecture_description_path,
        shared_reader=self.reader,
    )
    self._cache: dict[str, Any] | None = None

@staticmethod
def _path_key(alignment: Mapping[str, Any], record: Mapping[str, Any]) -> str:
    return repository_path_key(record.get('repository_id'), record['path'])

def _repository_reader(self, identifier: str | None) -> GitProjectReader:
    if identifier not in self.repository_readers:
        raise ProjectImplementationAlignmentError([f"Required observation repository is unavailable: {identifier}"])
    return self.repository_readers[identifier]

def load(self) -> dict[str, Any]:
    """Return one complete structurally valid alignment revision."""

    if self._cache is not None:
        return deepcopy(self._cache)
    try:
        model = self.reader.load_yaml(
            self.alignment_path,
            "项目实现对齐",
        )
    except GitProjectReaderError as error:
        raise ProjectImplementationAlignmentError([str(error)]) from error
    if not isinstance(model, Mapping):
        raise ProjectImplementationAlignmentError(["项目实现对齐必须是对象"])
    if model.get("schema_version") != PROJECT_IMPLEMENTATION_ALIGNMENT_SCHEMA:
        raise ProjectImplementationAlignmentError(
            ["项目实现对齐必须使用当前仓库限定的多语言观察合同"]
        )
    issues = _schema_issues(model, "项目实现对齐")
    artifacts: dict[str, dict[str, Any]] = {}
    artifact_paths = model.get("artifact_paths")
    if isinstance(artifact_paths, Mapping):
        try:
            self.reader.prefetch(
                [
                    repository_relative_path(
                        artifact_paths.get(name),
                        f"artifact_paths.{name}",
                    )
                    for name in _ARTIFACT_SCHEMAS
                ]
            )
        except GitProjectReaderError as error:
            issues.append(str(error))
        for name, expected_schema in _ARTIFACT_SCHEMAS.items():
            try:
                path = repository_relative_path(
                    artifact_paths.get(name),
                    f"artifact_paths.{name}",
                )
                value = self.reader.load_yaml(path, f"实现对齐产物 {name}")
            except GitProjectReaderError as error:
                issues.append(str(error))
                continue
            if not isinstance(value, Mapping):
                issues.append(f"实现对齐产物 {name} 必须是对象")
                continue
            if value.get("schema_version") != expected_schema:
                issues.append(
                    f"实现对齐产物 {name}.schema_version 必须是 "
                    f"{expected_schema}"
                )
                continue
            artifact_issues = _schema_issues(
                value,
                f"实现对齐产物 {name}",
            )
            issues.extend(artifact_issues)
            if artifact_issues:
                continue
            artifacts[name] = deepcopy(dict(value))
    if len(artifacts) == len(_ARTIFACT_SCHEMAS):
        self._validate_bindings(model, artifacts, issues)
        self._validate_authority_chain(model, issues)
        self._validate_coverage(model, artifacts, issues)
    if issues:
        raise ProjectImplementationAlignmentError(issues)

    result = deepcopy(dict(model))
    result.update(
        {
            "source_ownership": deepcopy(
                artifacts["source_ownership"]["records"]
            ),
            "governed_source_scopes": deepcopy(
                artifacts["source_ownership"]["governed_source_scopes"]
            ),
            "actual_dependencies": deepcopy(
                artifacts["actual_dependencies"]["records"]
            ),
            "target_responsibilities": deepcopy(
                artifacts["target_responsibilities"]["records"]
            ),
            "deviations": deepcopy(artifacts["deviations"]["deviations"]),
            "domain_fact_implementation": self._derive_fact_implementation(
                artifacts
            ),
            "_manifest_path": self.alignment_path,
            "_observed_commit": self.observed_commit,
            "semantic_content_machine_proven": False,
        }
    )
    self._cache = result
    return deepcopy(result)

def drift(
    self,
    *,
    mode: str = "daily",
    current_stage_id: str | None = None,
    external_providers: Sequence[ExternalObservationProvider] = (),
    external_execution_authorized: bool = False,
) -> dict[str, Any]:
    """Compare ledgers with one repeatable, explicitly authorized snapshot."""

    if mode not in {"daily", "stage"}:
        raise ProjectImplementationAlignmentError(
            ["漂移检查模式必须是 daily 或 stage"]
        )
    alignment = self.load()
    failures: list[str] = []
    counts: dict[str, Any] = {}
    hashes, manifest = self._governed_source_manifest(alignment)
    recorded_hashes = {
        self._path_key(alignment, item): item["sha256"]
        for item in alignment["source_ownership"]
    }
    if hashes != recorded_hashes:
        missing = sorted(set(hashes) - set(recorded_hashes))
        stale = sorted(set(recorded_hashes) - set(hashes))
        changed = sorted(
            path
            for path in set(hashes) & set(recorded_hashes)
            if hashes[path] != recorded_hashes[path]
        )
        if missing:
            failures.append("存在未归属受管实现文件：" + ", ".join(missing))
        if stale:
            failures.append("归属底账包含已不存在受管实现文件：" + ", ".join(stale))
        if changed:
            failures.append("受管实现文件变化后对齐未复核：" + ", ".join(changed))
    if (
        alignment["code_snapshot"]["governed_source_manifest_sha256"]
        != manifest
    ):
        failures.append("受管实现文件清单散列与当前快照不一致")
    try:
        for component in alignment["code_snapshot"]["repositories"]:
            component_reader = self._repository_reader(component["repository_id"])
            tip = component_reader.observed_commit or component_reader.resolve_commit("HEAD")
            if not component_reader.is_ancestor(component["base_commit"], tip):
                failures.append(f"Repository observation base is not an ancestor: {component['repository_id']}")
    except (GitProjectReaderError, ProjectImplementationAlignmentError) as error:
        failures.append(str(error))

    # The reviewed base commit is an ancestry anchor. Current validity is
    # decided by exact governed files plus either repeatable observation or
    # an exact-source replay of a previously authorized external receipt.
    recorded_external_keys = {
        (item["scope_id"], item["language_id"])
        for item in alignment["observation_coverage"]["records"]
        if item["execution_mode"] == "authorized_tool"
    }
    supplied_provider_keys = {
        (item.scope_id, item.language_id) for item in external_providers
    }
    observation: dict[str, Any] | None = None
    reused_recorded_observation = bool(recorded_external_keys) and not (
        external_providers
    )
    if reused_recorded_observation:
        failures.extend(
            self._recorded_observation_source_issues(alignment)
        )
    elif recorded_external_keys - supplied_provider_keys:
        missing_providers = sorted(
            recorded_external_keys - supplied_provider_keys
        )
        failures.append(
            "重新执行实现观察时缺少已记录的外部提供者："
            + ", ".join(
                f"{scope_id}/{language_id}"
                for scope_id, language_id in missing_providers
            )
        )
    else:
        try:
            observation = observe_project_implementation(self.repository_readers, alignment["observation_scopes"], external_providers=external_providers, external_execution_authorized=external_execution_authorized)
        except ImplementationObservationError as error:
            failures.extend(error.issues)
    if observation is not None:
        current_coverage = {
            "contract_version": observation["schema_version"],
            "overall_status": observation["overall_coverage_status"],
            "source_manifest_sha256": observation[
                "source_manifest_sha256"
            ],
            "observation_snapshot_sha256": observation[
                "observation_snapshot_sha256"
            ],
            "observed_paths": observation["observed_paths"],
            "records": observation["coverage"],
            "provider_receipts": observation["provider_receipts"],
        }
        if current_coverage != alignment["observation_coverage"]:
            failures.append(
                "实现观察范围、能力、覆盖或关系结果变化后对齐尚未复核"
            )
        if observation["overall_coverage_status"] != "complete":
            incomplete = [
                f"{item['scope_id']}/{item['language_id']}={item['status']}"
                for item in observation["coverage"]
                if item["status"] != "complete"
            ]
            failures.append(
                "实现观察未达到完整覆盖：" + ", ".join(incomplete)
            )
        scanned = normalized_observed_relations(observation)
        projection_fields = (
            "scope_id",
            "provider_id",
            "source_node_id",
            "source_node_kind",
            "source_path",
            "source_external_name",
            "target_node_id",
            "target_node_kind",
            "target_path",
            "target_external_name",
            "observed_names",
            "relation_kind",
            "resolution_status",
            "conditions",
        )
        projection_fields += ("repository_id",)
        scanned_projection = [
            {field: item[field] for field in projection_fields}
            for item in scanned
        ]
        recorded_projection = sorted(
            (
                {field: item[field] for field in projection_fields}
                for item in alignment["actual_dependencies"]
            ),
            key=lambda item: (
                item["scope_id"],
                item["provider_id"],
                item["source_node_id"],
                item["target_node_id"],
                item["relation_kind"],
                item["resolution_status"],
                tuple(item["conditions"]),
            ),
        )
